/* List view: split pane, grid rows, badges, tiles. Colors come from --aq-* tokens. */

.aq-split {
    display: flex;
    flex: 1;
    min-height: 0;
}

.aq-split-main {
    flex: 1;
    min-width: 0;
    overflow: auto;
    background: var(--aq-surface);
}

.aq-inspector {
    width: 320px;
    flex-shrink: 0;
    overflow: auto;
    border-left: 1px solid var(--aq-border);
    background: var(--aq-background);
    padding: 20px;
    display: flex;
    flex-direction: column;
    gap: 18px;
}

.aq-thead, .aq-tr {
    display: grid;
    align-items: center;
    column-gap: 12px;
    padding: 0 22px;
}

.aq-thead {
    box-sizing: border-box;
    height: 30px;
    position: sticky;
    top: 0;
    z-index: 30;
    background: var(--aq-surface);
    border-bottom: 1px solid var(--aq-border);
    font-size: 11.5px;
    color: var(--aq-text-muted);
}

.aq-thead [data-sort] {
    cursor: default;
    user-select: none;
}

.aq-thead [data-sorted=true] {
    color: var(--aq-text);
    font-weight: 500;
}

.aq-thead [data-sort="total_pt"] {
    color: var(--aq-text);
    font-weight: 600;
}

.aq-tfoot {
    display: grid;
    align-items: center;
    column-gap: 12px;
    padding: 0 22px;
    min-width: 640px;
    min-height: 46px;
    position: sticky;
    bottom: 0;
    z-index: 2;
    container-type: scroll-state;
    background: var(--aq-surface);
    border-top: 1px solid var(--aq-border);
    font-weight: 600;
}

.aq-tfoot .aq-num {
    font-size: inherit;
}

.aq-tfoot::after {
    content: '';
    position: absolute;
    left: 0;
    right: 0;
    bottom: 0;
    border-bottom: 1px solid var(--aq-border);
    pointer-events: none;
}

@container scroll-state(stuck: bottom) {
    .aq-tfoot::after {
        display: none;
    }
}

.aq-tr {
    min-height: 46px;
    border-bottom: 1px solid var(--aq-separator);
    background: var(--aq-surface);
    cursor: default;
    width: 100%;
    text-align: left;
    border-left: 0;
    border-right: 0;
    border-top: 0;
    font: inherit;
    color: var(--aq-text);
}

.aq-tr:hover {
    background: var(--aq-hover);
}

.aq-tr[aria-selected=true] {
    background: var(--aq-accent-soft);
}

.aq-tr:focus-visible {
    outline: 2px solid var(--aq-accent);
    outline-offset: -2px;
}

.aq-group {
    .aq-inspector {
        width: 280px;
    }
}

@media (max-width: 820px) {
    .aq-split {
        flex-direction: column;
        overflow: auto;
    }
    .aq-split-main {
        overflow: visible;
        flex: none;
    }
    .aq-inspector {
        width: auto;
        border-left: 0;
        border-top: 1px solid var(--aq-border);
        overflow: visible;
    }
    .aq-thead, .aq-tr {
        min-width: 640px;
    }
}

